using UnityEngine;

// 살펴보기: 주인공이 가까이에서 Space를 누르면 제목과 글을 대화창에 보여 줘요.
// 쪽지 · 책장 · 잠긴 상자가 모두 이 스크립트를 써요 (인스펙터에서 글만 다르게)
public class Readable : MonoBehaviour
{
    public string title = "쪽지";
    public string text = "아무것도 적혀 있지 않다.";

    void OnInteract()
    {
        Dialog.Show(title, text);
    }
}

using UnityEngine;

// 레버: 가까이에서 Space를 누르면 당겨져요.
// 세 레버를 정해진 순서(order)대로 모두 당기면 상자가 열리고, 틀리면 모두 제자리로 돌아가요.
// 쓰인 코드: OnInteract · Inventory(레버끼리 함께 쓰는 숫자) · GameObject.Find · transform.eulerAngles · Message.Show
public class Lever : MonoBehaviour
{
    [Tooltip("이 레버를 몇 번째로 당겨야 하나요? (1 ~ 3)")]
    public int order = 1;
    public string color = "빨강";

    // 레버 세 개가 함께 보는 「지금까지 맞게 당긴 수」는 소지품에 숫자로 넣어 둬요
    const string STEP = "레버 단계";

    void OnInteract()
    {
        // 손잡이가 오른쪽으로 돌아가 있으면(회전 70도) 이미 당긴 레버예요
        if (transform.eulerAngles.z != 0)
        {
            Message.Show("이미 당긴 레버예요");
            return;
        }

        int step = Inventory.Count(STEP);
        if (order == step + 1)                  // 순서가 맞았어요
        {
            transform.eulerAngles = new Vector3(0, 0, 70);   // 손잡이를 오른쪽으로 당겨요
            Inventory.Add(STEP, 1);
            Sfx("레버 소리");
            Message.Show(color + " 레버를 당겼어요 (" + (step + 1) + " / 3)");
            if (step + 1 == 3)
            {
                OpenChest();
            }
        }
        else                                     // 틀렸어요 → 처음부터
        {
            Message.Show("덜컹! 순서가 틀려서 레버가 모두 제자리로 돌아갔어요", 2.5f);
            Sfx("레버 소리");
            ResetAll();
        }
    }

    void OpenChest()
    {
        GameObject.Find("잠긴 상자").SetActive(false);
        GameObject.Find("열린 상자").SetActive(true);
        UIScreen.SetText("목표", "내용", "어딘가에서 상자가 열렸어요!");
        Debug.Log("레버 퍼즐 성공 → 상자 열림");
    }

    void ResetAll()
    {
        Inventory.Remove(STEP, Inventory.Count(STEP));
        GameObject.Find("빨강 레버").transform.eulerAngles = new Vector3(0, 0, 0);
        GameObject.Find("초록 레버").transform.eulerAngles = new Vector3(0, 0, 0);
        GameObject.Find("파랑 레버").transform.eulerAngles = new Vector3(0, 0, 0);
    }

    // ▼ 직접 만든 메서드: 씬의 「효과음」 오브젝트에 붙은 오디오 소스로 이름이 같은 오디오 클립을 겹쳐 재생해요
    //   PlayOneShot("클립 이름")은 지금 나는 소리를 끊지 않고 하나 더 겹쳐서 틀어요
    void Sfx(string clip)
    {
        GameObject.Find("효과음").GetComponent<AudioSource>().PlayOneShot(clip);
    }
}

using UnityEngine;

// 열린 상자: 처음 살펴보면 열쇠를 소지품에 넣어요.
public class TreasureChest : MonoBehaviour
{
    bool taken = false;

    void OnInteract()
    {
        if (taken)
        {
            Dialog.Show("상자", "이제 텅 비어 있다.");
            return;
        }
        taken = true;
        Inventory.Add("열쇠", 1);
        Sfx("상자 반짝");
        Dialog.Show("상자", "작은 황금 열쇠를 찾았다!");
        UIScreen.SetText("목표", "내용", "열쇠로 문을 열어 보세요");
        UIScreen.SetText("목표", "열쇠", "열쇠 1");
    }

    // ▼ 직접 만든 메서드: 씬의 「효과음」 오브젝트에 붙은 오디오 소스로 이름이 같은 오디오 클립을 겹쳐 재생해요
    //   PlayOneShot("클립 이름")은 지금 나는 소리를 끊지 않고 하나 더 겹쳐서 틀어요
    void Sfx(string clip)
    {
        GameObject.Find("효과음").GetComponent<AudioSource>().PlayOneShot(clip);
    }
}

using UnityEngine;

// 잠긴 문: 열쇠가 있으면 열리고(오브젝트가 사라져 지나갈 수 있어요), 없으면 잠겨 있다고 알려 줘요.
// 문에는 트리거가 꺼진 박스 콜라이더 2D가 있어서 주인공을 막아요.
public class LockedDoor : MonoBehaviour
{
    public string keyName = "열쇠";

    void OnInteract()
    {
        if (Inventory.Has(keyName))
        {
            Inventory.Remove(keyName, 1);
            UIScreen.SetText("목표", "열쇠", "열쇠 0");
            UIScreen.SetText("목표", "내용", "문 밖으로 나가세요!");
            Message.Show("철컥! 문이 열렸어요");
            Sfx("문 열림");
            gameObject.SetActive(false);
        }
        else
        {
            Dialog.Show("문", "굳게 잠겨 있다. 열쇠가 필요해 보인다.");
        }
    }

    // ▼ 직접 만든 메서드: 씬의 「효과음」 오브젝트에 붙은 오디오 소스로 이름이 같은 오디오 클립을 겹쳐 재생해요
